"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1753],{91753:a=>{a.exports=JSON.parse('{"slug":"aktivy-nestle-auchan-vremennoe-upravlenie","locale":"zh","title":"Nestle、Auchan、Lemana Pro和FM Logistic的俄罗斯资产交由LEV Management临时管理","description":"总统令将Nestle、Auchan、Lemana Pro和FM Logistic的俄罗斯资产交由LEV Management临时管理。管理人已致信Auchan，承诺门店与采购不会停顿。纸面所有者未变，控制权已经转移。","blocks":[{"id":"b001","kind":"paragraph","text":"总统令将四家公司的俄罗斯资产置于LEV Management旗下机构控制。Auchan方面，Auchan有限责任公司100%的股权被纳入临时管理。这是俄罗斯对所谓不友好国家企业实施强制产权控制的一系列举措之一。2022年后，西方企业试图出售俄罗斯子公司或停止经营，但能否退出已取决于当局许可，而不再只是所有者意愿。"},{"id":"b002","kind":"paragraph","text":"这家管理公司成立于2025年末，由一位内务部将军领导，缺乏公开的零售或物流经营履历。LEV Management总经理安德烈\xb7克拉尤什金致信Auchan管理层，承诺保持连锁体系完整，不中断采购、供货和门店运营，并履行对消费者、供应商与员工的义务。他将Auchan的稳定经营与食品安全联系起来。"},{"id":"b003","kind":"paragraph","text":"信中也有意外内容。克拉尤什金承诺保护连锁企业的不动产免遭包括无人机在内的袭击，并保留Auchan现任管理层，不改变其工作条件。Auchan确认收到来信，表示愿与管理人开展工作合作，并称所有设施均正常运行。"},{"id":"b004","kind":"paragraph","text":"四项资产规模各异。Auchan在俄罗斯有241家门店，其中62家大卖场，员工超过33千人。Lemana Pro即原Leroy Merlin，与Auchan同属穆里耶家族。俄罗斯占Nestle全球销售额略高于1%，而2022年前约为2%；公司已收缩大部分销售、进口、广告与投资。FM Logistic的核心资产并非仓库，而是合同、线路和客户信任，这些无法靠法令直接转交。"},{"id":"b005","kind":"paragraph","text":"“临时管理”的机制比名称简单。设想一套房产，文件中的业主不变，但钥匙、租约与租金都交给被任命的管理人。产权仍在，决策和现金流却归他人控制。形式上可逆，也不称为没收；实际上，原业主已无法自由出售资产、选择买家或锁定价格。"},{"id":"b006","kind":"paragraph","text":"对Auchan消费者，目前没有变化，这是连锁企业自己的表态。书面承诺包括保留管理层、履行对员工和供应商的义务。承诺并非保证，但已落在纸上，企业也确认收到。风险在别处：Nestle进口商品，以及FM Logistic与外国客户的合同；客户可能不愿与新状态下的资产合作。目前没有规模估计。"},{"id":"b007","kind":"paragraph","text":"尚不清楚所有者能否获赔、商品种类会否改变，以及临时管理会否永久化。普通人因新闻而在Auchan囤货，是为企业已公开否认的恐慌支付全价；但说管理人更换与谁都无关也不成立。对33千员工，这是工资问题；对消费者，则是谁以何种动机决定货架上卖什么。"}],"sources":[{"label":"https://www.kommersant.ru/doc/8971025","url":"https://www.kommersant.ru/doc/8971025"},{"label":"https://tass.ru/ekonomika/28132697","url":"https://tass.ru/ekonomika/28132697"},{"label":"https://finance.yahoo.com/economy/policy/articles/russia-seizes-assets-nestle-french-102315087.html","url":"https://finance.yahoo.com/economy/policy/articles/russia-seizes-assets-nestle-french-102315087.html"}],"sourceBodySha256":"cf5b07eda074b3ba8f645b2e30d77d8c2bb3b88d7ecf919b61965f4aca16693c"}')}}]);